#!/usr/bin/env python3
"""Retain the generated BDN drivers and their build outputs before checkout cleanup."""

import argparse
import hashlib
import json
from pathlib import Path
import shutil
import subprocess


def retain(checkout, destination):
    checkout, destination = Path(checkout).resolve(), Path(destination).resolve()
    if destination.exists():
        raise ValueError(f"Evidence destination already exists: {destination}")
    output = checkout / "benchmarks/Relayer.Benchmarks/bin/Release"
    projects = sorted(output.rglob("BenchmarkDotNet.Autogenerated.csproj"))
    if not projects:
        raise ValueError(f"No retained BenchmarkDotNet generated projects under {output}; use --keepFiles")
    destination.mkdir(parents=True)
    files = []

    def copy(source, relative):
        if source.is_symlink():
            raise ValueError(f"Cannot retain symlink: {source}")
        target = destination / relative
        target.parent.mkdir(parents=True, exist_ok=True)
        shutil.copyfile(source, target)
        digest = hashlib.sha256(source.read_bytes()).hexdigest()
        if hashlib.sha256(target.read_bytes()).hexdigest() != digest:
            raise ValueError(f"Evidence copy differs: {source}")
        files.append({"path": relative.as_posix(), "source": str(source),
                      "length": target.stat().st_size, "sha256": digest})

    # Each generated directory includes the .notcs driver, project, scripts, and the
    # actual executable's dependency closure. Keep all launches, including failed ones.
    for project in projects:
        for source in sorted(project.parent.rglob("*")):
            # Compiler intermediates duplicate the retained final binaries. They are
            # not the images loaded by the benchmark process.
            if "obj" in source.relative_to(project.parent).parts:
                continue
            if source.is_symlink():
                raise ValueError(f"Cannot retain symlink: {source}")
            if source.is_file():
                copy(source, Path("builds") / source.relative_to(output))

    # The git archive plus the effective common harness reconstructs CI's overlay.
    subprocess.run(["git", "-C", str(checkout), "archive", "--format=zip", "HEAD",
                    "-o", str(destination / "source.zip")], check=True)
    harness = checkout / "benchmarks/Relayer.Benchmarks"
    for source in [checkout / "global.json", harness / "Program.cs", harness / "Relayer.Benchmarks.csproj",
                   *sorted((harness / "RegressionGate").rglob("*.cs"))]:
        copy(source, Path("overlay") / source.relative_to(checkout))
    archive = destination / "source.zip"
    files.append({"path": "source.zip", "length": archive.stat().st_size,
                  "sha256": hashlib.sha256(archive.read_bytes()).hexdigest()})
    commit = subprocess.run(["git", "-C", str(checkout), "rev-parse", "HEAD"],
                            check=True, capture_output=True, text=True).stdout.strip()
    manifest = {"commit": commit, "checkout": str(checkout), "files": files,
                "reconstruction": "Extract source.zip; delete benchmark C# except Program.cs and RegressionGate/; replace RegressionGate/ and apply overlay/."}
    (destination / "inventory-sha256.json").write_text(json.dumps(manifest, indent=2) + "\n", encoding="utf-8")
    return manifest


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("checkout", type=Path)
    parser.add_argument("destination", type=Path)
    args = parser.parse_args()
    manifest = retain(args.checkout, args.destination)
    print(f"Retained and hash-verified {len(manifest['files'])} files for {manifest['commit']}")


if __name__ == "__main__":
    main()
